38	public interface Task {
39	
40	    // this must be negative to distinguish a running active task from other kinds of tasks
41	    // which may be caught up to the same offsets
42	    long LATEST_OFFSET = -2L;
43	
44	    /*
45	     * <pre>
46	     *                 +---------------+
47	     *          +----- |  Created (0)  | <---------+
48	     *          |      +-------+-------+           |
49	     *          |              |                   |
50	     *          |              v                   |
51	     *          |      +-------+-------+           |
52	     *          +----- | Restoring (1) | <---+     |
53	     *          |      +-------+-------+     |     |
54	     *          |              |             |     |
55	     *          |              v             |     |
56	     *          |      +-------+-------+     |     |
57	     *          |      |  Running (2)  |     |     |
58	     *          |      +-------+-------+     |     |
59	     *          |              |             |     |
60	     *          |              v             |     |
61	     *          |     +--------+-------+     |     |
62	     *          +---> |  Suspended (3) | ----+     |    //TODO Suspended(3) could be removed after we've stable on KIP-429
63	     *                +--------+-------+           |
64	     *                         |                   |
65	     *                         v                   |
66	     *                +--------+-------+           |
67	     *                |   Closed (4)   | ----------+
68	     *                +----------------+
69	     * </pre>
70	     */
71	    enum State {
72	        CREATED(1, 3),            // 0
73	        RESTORING(2, 3),          // 1
74	        RUNNING(3),               // 2
75	        SUSPENDED(1, 4),          // 3
76	        CLOSED(0);                // 4, we allow CLOSED to transit to CREATED to handle corrupted tasks
77	
78	        private final Set<Integer> validTransitions = new HashSet<>();
79	
80	        State(final Integer... validTransitions) {
81	            this.validTransitions.addAll(Arrays.asList(validTransitions));
82	        }
83	
84	        public boolean isValidTransition(final State newState) {
85	            return validTransitions.contains(newState.ordinal());
86	        }
87	    }
88	
89	    enum TaskType {
90	        ACTIVE("ACTIVE"),
91	
92	        STANDBY("STANDBY"),
93	
94	        GLOBAL("GLOBAL");
95	
96	        public final String name;
97	
98	        TaskType(final String name) {
99	            this.name = name;
100	        }
101	    }
102	
103	
104	    // idempotent life-cycle methods
105	
106	    /**
107	     * @throws TaskCorruptedException if the state cannot be reused (with EOS) and needs to be reset
108	     * @throws LockException    could happen when multi-threads within the single instance, could retry
109	     * @throws StreamsException fatal error, should close the thread
110	     */
111	    void initializeIfNeeded();
112	
113	    default void addPartitionsForOffsetReset(final Set<TopicPartition> partitionsForOffsetReset) {
114	        throw new UnsupportedOperationException();
115	    }
116	
117	    /**
118	     * @throws StreamsException fatal error, should close the thread
119	     */
120	    void completeRestoration(final java.util.function.Consumer<Set<TopicPartition>> offsetResetter);
121	
122	    void suspend();
123	
124	    /**
125	     * @throws StreamsException fatal error, should close the thread
126	     */
127	    void resume();
128	
129	    /**
130	     * Must be idempotent.
131	     */
132	    void closeDirty();
133	
134	    /**
135	     * Must be idempotent.
136	     */
137	    void closeClean();
138	
139	
140	    // non-idempotent life-cycle methods
141	
142	    /**
143	     * Updates input partitions and topology after rebalance
144	     */
145	    void updateInputPartitions(final Set<TopicPartition> topicPartitions, final Map<String, List<String>> allTopologyNodesToSourceTopics);
146	
147	    /**
148	     * @param enforceCheckpoint if true the task would always execute the checkpoint;
149	     *                          otherwise it may skip if the state has not advanced much
150	     */
151	    void maybeCheckpoint(final boolean enforceCheckpoint);
152	
153	    void markChangelogAsCorrupted(final Collection<TopicPartition> partitions);
154	
155	    /**
156	     * Revive a closed task to a created one; should never throw an exception
157	     */
158	    void revive();
159	
160	    /**
161	     * Close the task except the state, so that the states can be later recycled
162	     */
163	    void prepareRecycle();
164	
165	    /**
166	     * Resumes polling in the main consumer for all partitions for which
167	     * the corresponding record queues have capacity (again).
168	     */
169	    void resumePollingForPartitionsWithAvailableSpace();
170	
171	    /**
172	     * Fetches up-to-date lag information from the consumer.
173	     */
174	    void updateLags();
175	
176	    // runtime methods (using in RUNNING state)
177	
178	    void addRecords(TopicPartition partition, Iterable<ConsumerRecord<byte[], byte[]>> records);
179	
180	    default void updateNextOffsets(final TopicPartition partition, final OffsetAndMetadata offsetAndMetadata) {
181	    }
182	
