57	/**
58	 * ProcessorStateManager is the source of truth for the current offset for each state store,
59	 * which is either the read offset during restoring, or the written offset during normal processing.
60	 *
61	 * <p>The offset is initialized as null when the state store is registered, and then it can be updated by
62	 * loading checkpoint file, restore state stores, or passing from the record collector's written offsets.
63	 *
64	 * <p>When checkpointing, if the offset is not null it would be written to the file.
65	 *
66	 * <p>The manager is also responsible for restoring state stores via their registered restore callback,
67	 * which is used for both updating standby tasks as well as restoring active tasks.
68	 */
69	public class ProcessorStateManager implements StateManager {
70	
71	    public static class StateStoreMetadata {
72	        private final StateStore stateStore;
73	
74	        // corresponding changelog partition of the store, this and the following two fields
75	        // will only be not-null if the state store is logged (i.e. changelog partition and restorer provided)
76	        private final TopicPartition changelogPartition;
77	
78	        // could be used for both active restoration and standby
79	        private final StateRestoreCallback restoreCallback;
80	
81	        private final CommitCallback commitCallback;
82	
83	        // record converters used for restoration and standby
84	        private final RecordConverter recordConverter;
85	
86	        // indicating the current snapshot of the store as the offset of last changelog record that has been
87	        // applied to the store used for both restoration (active and standby tasks restored offset) and
88	        // normal processing that update stores (written offset); could be null (when initialized)
89	        //
90	        // the offset is updated in three ways:
91	        //   1. when loading from the checkpoint file, when the corresponding task has acquired the state
92	        //      directory lock and have registered all the state store; it is only one-time
93	        //   2. when updating with restore records (by both restoring active and standby),
94	        //      update to the last restore record's offset
95	        //   3. when checkpointing with the given written offsets from record collector,
96	        //      update blindly with the given offset
97	        private Long offset;
98	
99	        // Will be updated on batch restored
100	        private Long endOffset;
101	        // corrupted state store should not be included in checkpointing
102	        private boolean corrupted;
103	
104	
105	        private StateStoreMetadata(final StateStore stateStore,
106	                                   final CommitCallback commitCallback) {
107	            this.stateStore = stateStore;
108	            this.commitCallback = commitCallback;
109	            this.restoreCallback = null;
110	            this.recordConverter = null;
111	            this.changelogPartition = null;
112	            this.corrupted = false;
113	            this.offset = null;
114	        }
115	
116	        private StateStoreMetadata(final StateStore stateStore,
117	                                   final TopicPartition changelogPartition,
118	                                   final StateRestoreCallback restoreCallback,
119	                                   final CommitCallback commitCallback,
120	                                   final RecordConverter recordConverter) {
121	            if (restoreCallback == null) {
122	                throw new IllegalStateException("Log enabled store should always provide a restore callback upon registration");
123	            }
124	
125	            this.stateStore = stateStore;
126	            this.changelogPartition = changelogPartition;
127	            this.restoreCallback = restoreCallback;
128	            this.commitCallback = commitCallback;
129	            this.recordConverter = recordConverter;
130	            this.offset = null;
131	        }
132	
133	        private void setOffset(final Long offset) {
134	            this.offset = offset;
135	        }
136	
137	        // the offset is exposed to the changelog reader to determine if restoration is completed
138	        Long offset() {
139	            return this.offset;
140	        }
141	
142	        Long endOffset() {
143	            return this.endOffset;
144	        }
145	
146	        public void setEndOffset(final Long endOffset) {
147	            this.endOffset = endOffset;
148	        }
149	
150	        TopicPartition changelogPartition() {
151	            return this.changelogPartition;
152	        }
153	
154	        StateStore store() {
155	            return LegacyCheckpointingStateStore.maybeUnwrapStore(this.stateStore);
156	        }
157	
158	        void markCorrupted() {
159	            this.corrupted = true;
160	            LegacyCheckpointingStateStore.maybeMarkCorrupted(this.stateStore);
161	        }
162	
163	        @Override
164	        public String toString() {
165	            return "StateStoreMetadata (" + stateStore.name() + " : " + changelogPartition + " @ " + offset;
166	        }
167	    }
168	
169	    private static final String STATE_CHANGELOG_TOPIC_SUFFIX = "-changelog";
