41	import static org.apache.kafka.streams.processor.internals.metrics.StreamsMetricsImpl.maybeRecordSensor;
42	
43	/**
44	 * A StandbyTask
45	 */
46	public class StandbyTask extends AbstractTask implements Task {
47	    private final boolean eosEnabled;
48	    private final Sensor closeTaskSensor;
49	    private final Sensor updateSensor;
50	    private final StreamsMetricsImpl streamsMetrics;
51	
52	    protected final InternalProcessorContext<?, ?> processorContext;
53	
54	    /**
55	     * @param id              the ID of this task
56	     * @param inputPartitions input topic partitions, used for thread metadata only
57	     * @param topology        the instance of {@link ProcessorTopology}
58	     * @param config          the {@link StreamsConfig} specified by the user
59	     * @param streamsMetrics  the {@link StreamsMetrics} created by the thread
60	     * @param stateMgr        the {@link ProcessorStateManager} for this task
61	     * @param stateDirectory  the {@link StateDirectory} created by the thread
62	     */
63	    StandbyTask(final TaskId id,
64	                final Set<TopicPartition> inputPartitions,
65	                final ProcessorTopology topology,
66	                final TaskConfig config,
67	                final StreamsMetricsImpl streamsMetrics,
68	                final ProcessorStateManager stateMgr,
69	                final StateDirectory stateDirectory,
70	                final ThreadCache cache,
71	                final InternalProcessorContext<?, ?> processorContext) {
72	        super(
73	            id,
74	            topology,
75	            stateDirectory,
76	            stateMgr,
77	            inputPartitions,
78	            config,
79	            "standby-task",
80	            StandbyTask.class
81	        );
82	        this.processorContext = processorContext;
83	        this.streamsMetrics = streamsMetrics;
84	        processorContext.transitionToStandby(cache);
85	
86	        closeTaskSensor = ThreadMetrics.closeTaskSensor(Thread.currentThread().getName(), streamsMetrics);
87	        updateSensor = TaskMetrics.updateSensor(Thread.currentThread().getName(), id.toString(), streamsMetrics);
88	        this.eosEnabled = config.eosEnabled;
89	    }
90	
91	    @Override
92	    public boolean isActive() {
93	        return false;
94	    }
95	
96	    @Override
97	    public void recordRestoration(final Time time, final long numRecords, final boolean initRemaining) {
98	        if (initRemaining) {
99	            throw new IllegalStateException("Standby task would not record remaining records to restore");
100	        }
101	
102	        maybeRecordSensor(numRecords, time, updateSensor);
103	    }
104	
105	    /**
106	     * @throws TaskCorruptedException if the state cannot be reused (with EOS) and needs to be reset)
107	     * @throws StreamsException fatal error, should close the thread
108	     */
109	    @Override
110	    public void initializeIfNeeded() {
111	        if (state() == State.CREATED) {
112	            StateManagerUtil.registerStateStores(log, logPrefix, topology, stateMgr, stateDirectory, processorContext);
113	
114	            // with and without EOS we would check for checkpointing at each commit during running,
115	            // and the file may be deleted in which case we should checkpoint immediately,
116	            // therefore we initialize the snapshot as empty
117	            offsetSnapshotSinceLastFlush = Collections.emptyMap();
118	
119	            // no topology needs initialized, we can transit to RUNNING
120	            // right after registered the stores
121	            transitionTo(State.RESTORING);
122	            transitionTo(State.RUNNING);
123	
124	            processorContext.initialize();
125	
126	            log.info("Initialized");
127	        } else if (state() == State.RESTORING) {
128	            throw new IllegalStateException("Illegal state " + state() + " while initializing standby task " + id);
129	        }
130	    }
131	
132	    @Override
133	    public void completeRestoration(final java.util.function.Consumer<Set<TopicPartition>> offsetResetter) {
134	        throw new IllegalStateException("Standby task " + id + " should never be completing restoration");
135	    }
136	
137	    @Override
