56	    public GlobalStateUpdateTask(final LogContext logContext,
57	                                 final ProcessorTopology topology,
58	                                 final InternalProcessorContext<?, ?> processorContext,
59	                                 final GlobalStateManager stateMgr,
60	                                 final DeserializationExceptionHandler deserializationExceptionHandler,
